#include <stdio.h>

int main() {
    float a, b;
    char op;
    printf("输入表达式(如3+5): ");
    scanf("%f%c%f", &a, &op, &b);
    float result = (op=='+') ? a+b :
                   (op=='-') ? a-b :
                   (op=='*') ? a*b :
                   (op=='/') ? a/b : 0;
    printf("%.2f %c %.2f = %.2f\n", a, op, b, result);
    return 0;
}

