#include <stdio.h>

int main() {
    float weight, height;
    printf("输入体重(kg)和身高(m): ");
    scanf("%f %f", &weight, &height);
    float bmi = weight / (height * height);
    printf("BMI = %.1f\n", bmi);
    const char* status = (bmi < 18.5f) ? "偏瘦" :
                         (bmi < 24.0f) ? "正常" :
                         (bmi < 28.0f) ? "偏胖" : "肥胖";
    printf("%s\n", status);
    return 0;
}

